package com.myaaptha.domain.health;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="health_measurements") public class HealthMeasurementEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="report_id",nullable=false)Long reportId;@Column(name="metric_name",nullable=false,length=120)@jakarta.persistence.Convert(converter = com.myaaptha.platform.security.EncryptedTextConverter.class) String metricName;@Column(name="measured_value",nullable=false,columnDefinition="TEXT")@Convert(converter=com.myaaptha.platform.security.EncryptedDecimalConverter.class) BigDecimal value;@Column(nullable=false,length=40)@jakarta.persistence.Convert(converter = com.myaaptha.platform.security.EncryptedTextConverter.class) String unit;@Column(name="reference_min",columnDefinition="TEXT")@Convert(converter=com.myaaptha.platform.security.EncryptedDecimalConverter.class) BigDecimal referenceMin;@Column(name="reference_max",columnDefinition="TEXT")@Convert(converter=com.myaaptha.platform.security.EncryptedDecimalConverter.class) BigDecimal referenceMax;@Column(length=500)@jakarta.persistence.Convert(converter = com.myaaptha.platform.security.EncryptedTextConverter.class) String suggestion;public Long getId(){return id;}public Long getReportId(){return reportId;}public void setReportId(Long v){reportId=v;}public String getMetricName(){return metricName;}public void setMetricName(String v){metricName=v;}public BigDecimal getValue(){return value;}public void setValue(BigDecimal v){value=v;}public String getUnit(){return unit;}public void setUnit(String v){unit=v;}public BigDecimal getReferenceMin(){return referenceMin;}public void setReferenceMin(BigDecimal v){referenceMin=v;}public BigDecimal getReferenceMax(){return referenceMax;}public void setReferenceMax(BigDecimal v){referenceMax=v;}public String getSuggestion(){return suggestion;}public void setSuggestion(String v){suggestion=v;}}
